  HWTEST_INFO("button",
              "please press KEY2 (PA43) %d times (%ds timeout)",
              BTN_N_EVENTS / 2, BTN_TIMEOUT_MS / 1000);

  pfd.fd     = fd;
  pfd.events = POLLIN;

  for (i = 0; i < BTN_N_EVENTS; i++)
    {
      /* 切换到阻塞模式 poll */

      ret = poll(&pfd, 1, BTN_TIMEOUT_MS);
      if (ret <= 0)
        {
          HWTEST_FAIL("button",
                      "poll timeout at event %d — "
                      "no button press detected",
                      i);
          ret = -1;
          goto out;
        }

      /* 读取按键状态 */

      ret = read(fd, &sample, sizeof(sample));
      if (ret < (int)sizeof(sample))
        {
          HWTEST_FAIL("button", "read failed at event %d: %d", i, errno);
          ret = -1;
          goto out;
        }

      if (sample & 0x01)
        {
          press_count++;
          HWTEST_INFO("button", "event[%d]: KEY2 PRESSED  (mask=0x%02X)",
                      i, sample);
        }
      else
        {
          release_count++;
          HWTEST_INFO("button", "event[%d]: KEY2 RELEASED (mask=0x%02X)",
                      i, sample);
        }
    }

  /* ── 步骤 4：验证结果 ──────────────────────────────────────────── */

  if (press_count > 0 && release_count > 0)
    {
      HWTEST_PASS("button",
                  "KEY2 pressed %d times, released %d times",
                  press_count, release_count);
    }
  else if (press_count > 0)
    {
      HWTEST_PASS("button",
                  "KEY2 pressed %d times (no release captured)",
                  press_count);
    }
  else
    {
      HWTEST_FAIL("button",
                  "no KEY2 press events captured in %d events",
                  BTN_N_EVENTS);
      ret = -1;
    }

out:
  if (fd >= 0)
    {
      close(fd);
    }

  return ret;
}

/****************************************************************************
 * apps/examples/hwtest/test_tfcard.c
 *
 * 测试项 #9：TF 卡 (FATFS 读写)
 *
 * 说明：
 *   黄山派通过 SPI1 连接 TF 卡，但物理卡槽可能未焊接。
 *   此测试先检测设备节点是否存在，再尝试挂载和读写。
 *
 * 验证内容：
 *   1. /dev/mmcsd0 设备节点存在
 *   2. /data/tf 挂载点可访问
 *   3. 写入测试文件，读回并校验
 *   4. 清理测试文件
 *
 * 使用的 API：
 *   - /dev/mmcsd0：NuttX MMC/SD SPI 驱动自动注册
 *   - 标准文件 I/O：open/write/read/close, stat()
 *
 * 预期结果：
 *   [PASS] tfcard: mount OK, write/read/verify OK
 *   或
 *   [SKIP] tfcard: TF card not detected (card slot empty)
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include "hwtest.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TF_TEST_FILE    HWTEST_TF_MOUNT "/hwtest_tf.dat"
#define TF_TEST_SIZE    256
#define TF_TEST_PATTERN 0xA5

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_tfcard(int argc, char *argv[])
{
  uint8_t wbuf[TF_TEST_SIZE];
  uint8_t rbuf[TF_TEST_SIZE];
  struct stat st;
  int fd = -1;
  int ret = 0;
  int i;
  int nbytes;

  printf("\n--- 测试 #9: TF 卡 (FATFS 读写) ---\n\n");

  /* ── 步骤 1：检查设备节点 ──────────────────────────────────────── */

  if (stat(HWTEST_TF_RAW_DEV, &st) < 0)
    {
      HWTEST_SKIP("tfcard",
                  "device %s not found — "
                  "check SPI1 wiring or insert TF card",
                  HWTEST_TF_RAW_DEV);
      return 0;
    }

  HWTEST_INFO("tfcard", "raw device %s exists", HWTEST_TF_RAW_DEV);

  /* ── 步骤 2：检查挂载点 ────────────────────────────────────────── */

  if (stat(HWTEST_TF_MOUNT, &st) < 0)
    {
      HWTEST_SKIP("tfcard",
                  "mount point %s not accessible — "
                  "TF card may not be inserted or FAT mount failed",
                  HWTEST_TF_MOUNT);
      return 0;
    }

  if (!S_ISDIR(st.st_mode))
    {
      HWTEST_FAIL("tfcard", "%s is not a directory", HWTEST_TF_MOUNT);
      return -1;
    }

  HWTEST_INFO("tfcard", "mount point %s accessible", HWTEST_TF_MOUNT);

  /* ── 步骤 3：写入测试文件 ──────────────────────────────────────── */

  memset(wbuf, TF_TEST_PATTERN, TF_TEST_SIZE);
  for (i = 0; i < TF_TEST_SIZE; i++)
    {
      wbuf[i] = (uint8_t)(TF_TEST_PATTERN + i);
    }

  fd = open(TF_TEST_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0666);
  if (fd < 0)
    {
      HWTEST_FAIL("tfcard", "create %s failed: %d", TF_TEST_FILE, errno);
      ret = -1;
      goto out;
    }

  nbytes = write(fd, wbuf, TF_TEST_SIZE);
  if (nbytes != TF_TEST_SIZE)
    {
      HWTEST_FAIL("tfcard", "write failed: wrote %d/%d bytes, errno=%d",
                  nbytes, TF_TEST_SIZE, errno);
      ret = -1;
      goto out;
    }

  close(fd);
  fd = -1;

  HWTEST_INFO("tfcard", "wrote %d bytes to %s", TF_TEST_SIZE, TF_TEST_FILE);

  /* ── 步骤 4：读回并校验 ────────────────────────────────────────── */

  fd = open(TF_TEST_FILE, O_RDONLY);
  if (fd < 0)
    {
      HWTEST_FAIL("tfcard", "open %s for read failed: %d",
                  TF_TEST_FILE, errno);
      ret = -1;
      goto out;
    }

  memset(rbuf, 0, TF_TEST_SIZE);
  nbytes = read(fd, rbuf, TF_TEST_SIZE);
  if (nbytes != TF_TEST_SIZE)
    {
      HWTEST_FAIL("tfcard", "read failed: got %d/%d bytes, errno=%d",
                  nbytes, TF_TEST_SIZE, errno);
      ret = -1;
      goto out;
    }

  close(fd);
  fd = -1;

  /* 逐字节校验 */

  for (i = 0; i < TF_TEST_SIZE; i++)
    {
      if (rbuf[i] != wbuf[i])
        {
          HWTEST_FAIL("tfcard",
                      "data mismatch at offset %d: "
                      "got 0x%02X, expect 0x%02X",
                      i, rbuf[i], wbuf[i]);
          ret = -1;
          goto cleanup;
        }
    }

  HWTEST_PASS("tfcard",
              "mount OK, write %d bytes, read-back verify OK",
              TF_TEST_SIZE);

cleanup:
  /* ── 步骤 5：清理测试文件 ──────────────────────────────────────── */

  unlink(TF_TEST_FILE);
  HWTEST_INFO("tfcard", "test file removed");

out:
  if (fd >= 0)
    {
      close(fd);
    }

  return ret;
}

/****************************************************************************
 * apps/examples/hwtest/test_rtc.c
 *
 * 测试项 #10：RTC 实时时钟 (SF32LB52 内置)
 *
 * 验证内容：
 *   1. RTC 设备 /dev/rtc0 可打开
 *   2. 设置时间（使用 RTC_SET_TIME ioctl）
 *   3. 读回时间并验证设置生效
 *   4. 等待 2 秒后读取，验证时间在前进
 *
 * 使用的 API：
 *   - /dev/rtc0：RTC_SET_TIME, RTC_RD_TIME (ioctl)
 *   - struct rtc_time (兼容 Linux RTC 接口)
 *
 * 预期结果：
 *   [PASS] rtc: set time to 2026-01-01 12:00:00
 *   [PASS] rtc: read back OK, time advancing
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <nuttx/timers/rtc.h>

#include "hwtest.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void print_rtc_time(FAR const char *prefix,
                           FAR const struct rtc_time *rt)
{
  printf("  %s: %04d-%02d-%02d %02d:%02d:%02d\n",
         prefix,
         rt->tm_year + 1900, rt->tm_mon + 1, rt->tm_mday,
         rt->tm_hour, rt->tm_min, rt->tm_sec);
}

static int rtc_time_to_seconds(FAR const struct rtc_time *rt)
{
  return rt->tm_hour * 3600 + rt->tm_min * 60 + rt->tm_sec;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_rtc(int argc, char *argv[])
{
  struct rtc_time rt_set;
  struct rtc_time rt_read;
  struct rtc_time rt_after;
  int fd = -1;
  int ret;
  int sec_before;
  int sec_after;

  printf("\n--- 测试 #10: RTC 实时时钟 ---\n\n");

  /* ── 步骤 1：打开 RTC 设备 ─────────────────────────────────────── */

  fd = open(HWTEST_RTC_DEV, O_RDONLY);
  if (fd < 0)
    {
      HWTEST_FAIL("rtc", "open %s failed: %d", HWTEST_RTC_DEV, errno);
      return -1;
    }

  /* ── 步骤 2：先读取当前时间 ────────────────────────────────────── */

  memset(&rt_read, 0, sizeof(rt_read));
  ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_read);
  if (ret < 0)
    {
      HWTEST_FAIL("rtc", "RTC_RD_TIME failed: %d", ret);
      goto out;
    }

  print_rtc_time("current time", &rt_read);

  /* ── 步骤 3：设置测试时间 ──────────────────────────────────────── */

  memset(&rt_set, 0, sizeof(rt_set));
  rt_set.tm_year = 2026 - 1900;  /* 2026 年 */
  rt_set.tm_mon  = 1 - 1;        /* 1 月 (0-indexed) */
  rt_set.tm_mday = 1;
  rt_set.tm_hour = 12;
  rt_set.tm_min  = 0;
  rt_set.tm_sec  = 0;

  ret = ioctl(fd, RTC_SET_TIME, (unsigned long)&rt_set);
  if (ret < 0)
    {
      HWTEST_FAIL("rtc", "RTC_SET_TIME failed: %d", ret);
      goto out;
    }

  print_rtc_time("set time to", &rt_set);
  HWTEST_PASS("rtc", "set time to 2026-01-01 12:00:00");

  /* ── 步骤 4：读回验证 ──────────────────────────────────────────── */

  usleep(100000);  /* 100ms */

  memset(&rt_read, 0, sizeof(rt_read));
  ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_read);
  if (ret < 0)
    {
      HWTEST_FAIL("rtc", "RTC_RD_TIME after set failed: %d", ret);
      goto out;
    }

  print_rtc_time("read back", &rt_read);

  /* 验证年月日时分一致（秒可能差 1） */

  if (rt_read.tm_year != rt_set.tm_year ||
      rt_read.tm_mon  != rt_set.tm_mon ||
      rt_read.tm_mday != rt_set.tm_mday ||
      rt_read.tm_hour != rt_set.tm_hour ||
      rt_read.tm_min  != rt_set.tm_min)
    {
      HWTEST_FAIL("rtc", "read-back mismatch");
      ret = -1;
      goto out;
    }

  /* ── 步骤 5：等待 2 秒，验证时间在前进 ────────────────────────── */

  sec_before = rtc_time_to_seconds(&rt_read);
  sleep(2);

  memset(&rt_after, 0, sizeof(rt_after));
  ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_after);
  if (ret < 0)
    {
      HWTEST_FAIL("rtc", "RTC_RD_TIME after 2s failed: %d", ret);
      goto out;
    }

  sec_after = rtc_time_to_seconds(&rt_after);

  print_rtc_time("after 2s", &rt_after);

  if (sec_after > sec_before)
    {
      HWTEST_PASS("rtc",
                  "read back OK, time advancing (+%ds in 2s)",
                  sec_after - sec_before);
    }
  else if (sec_after == sec_before)
    {
      /* 可能刚好在秒边界，不算失败 */

      HWTEST_PASS("rtc", "read back OK, time consistent (same second)");
    }
  else
    {
      HWTEST_FAIL("rtc",
                  "time went backwards: before=%d after=%d",
                  sec_before, sec_after);
      ret = -1;
    }

  /* ── 步骤 6：恢复原始时间 ──────────────────────────────────────── */

  /* 注意：这里无法恢复，因为我们没有保存原始时间的完整秒数。
   * 在实际使用中，应通过 NTP 或手动设置恢复。
   */

  HWTEST_INFO("rtc",
              "test time left at 2026-01-01 — "
              "use 'date' command to restore correct time");

out:
  if (fd >= 0)
    {
      close(fd);
    }

  return ret;
}

