#define HWTEST_MAG_PID_VAL    0x0A

/* ── 环境光 ──────────────────────────────────────────────────────── */

#define HWTEST_ALS_I2C_BUS    0
#define HWTEST_ALS_ADDR       0x29

/* ── 麦克风 ──────────────────────────────────────────────────────── */

