/* ── 结果宏 ──────────────────────────────────────────────────────── */

#define HWTEST_PASS(tag, fmt, ...) \
  printf("[PASS] %s: " fmt "\n", tag, ##__VA_ARGS__)
#define HWTEST_FAIL(tag, fmt, ...) \
  printf("[FAIL] %s: " fmt "\n", tag, ##__VA_ARGS__)
#define HWTEST_SKIP(tag, fmt, ...) \
  printf("[SKIP] %s: " fmt "\n", tag, ##__VA_ARGS__)
