/****************************************************************************
 * packages/demos/huangshan_hwtest/hwtest_main.c
 *
 * 立创·黄山派 外设验证测试 —— 主入口
 *
 * 用法:
 *   nsh> hwtest all          # 全部测试
 *   nsh> hwtest amoled       # 单独测试
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include "hwtest.h"

typedef int (*hwtest_func_t)(int argc, char *argv[]);

struct hwtest_entry_s
{
  FAR const char *name;
  FAR const char *desc;
  hwtest_func_t   func;
};

static const struct hwtest_entry_s g_tests[] =
{
  { "all",     "运行全部外设测试",          test_all     },
  { "amoled",  "AMOLED 屏 + 触摸",         test_amoled  },
  { "imu",     "六轴 IMU (LSM6DS3TR-C)",   test_imu     },
  { "mag",     "三轴地磁 (MMC5603NJ)",      test_mag     },
  { "light",   "环境光 (LTR-303ALS)",       test_light   },
  { "mic",     "MEMS 麦克风 (PDM)",         test_mic     },
  { "rgbled",  "RGB LED (SK6812)",          test_rgbled  },
  { "vibrate", "震动马达",                   test_vibrate },
  { "button",  "功能按键 (KEY2)",            test_button  },
  { "tfcard",  "TF 卡 (FATFS 读写)",        test_tfcard  },
  { "rtc",     "RTC 实时时钟",               test_rtc     },
};

#define NTESTS (sizeof(g_tests) / sizeof(g_tests[0]))

int main(int argc, FAR char *argv[])
{
  int i;

  printf("========================================\n");
  printf("  立创·黄山派 外设验证测试 (SF32LB52)\n");
  printf("  Contest 2026 Team 307\n");
  printf("========================================\n\n");

  if (argc < 2)
    {
      printf("用法: hwtest <command>\n\n");
      printf("可用命令:\n");
      for (i = 0; i < NTESTS; i++)
        {
          printf("  %-10s %s\n", g_tests[i].name, g_tests[i].desc);
        }

      return 0;
    }

  for (i = 0; i < NTESTS; i++)
    {
      if (strcmp(argv[1], g_tests[i].name) == 0)
        {
          return g_tests[i].func(argc - 1, &argv[1]);
        }
    }

  printf("未知命令: %s\n", argv[1]);
  return -1;
}

/****************************************************************************
 * test_amoled.c — AMOLED 屏 + 触摸验证
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <poll.h>
#include <nuttx/video/fb.h>
#include <nuttx/input/touchscreen.h>
#include "hwtest.h"

static const uint16_t g_colors16[8] =
{
  0xf800, 0x07e0, 0x001f, 0xffff,
  0xffe0, 0x07ff, 0xf81f, 0x0000
};

static void draw_color_bars(FAR void *fbmem, int xres, int yres, int stride)
{
  int bar_w = xres / 8;
  int x, y, c;
  for (y = 0; y < yres; y++)
    {
      FAR uint16_t *row =
        (FAR uint16_t *)((FAR uint8_t *)fbmem + y * stride);
      for (x = 0; x < xres; x++)
        {
          c = x / bar_w;
          if (c > 7) c = 7;
          row[x] = g_colors16[c];
        }
    }
}

int test_amoled(int argc, char *argv[])
{
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  FAR void *fbmem = NULL;
  int fd_fb = -1, fd_touch = -1;
  int ret = 0, retry;

  printf("\n--- 测试 #1: AMOLED 屏 + 触摸 ---\n\n");

  /* 打开 Framebuffer */

  fd_fb = open(HWTEST_FB_DEV, O_RDWR);
  if (fd_fb < 0)
    {
      HWTEST_FAIL("amoled", "open %s failed: %d", HWTEST_FB_DEV, errno);
      return -1;
    }

  /* 查询视频信息 */

  if (ioctl(fd_fb, FBIOGET_VIDEOINFO, (unsigned long)&vinfo) < 0 ||
      ioctl(fd_fb, FBIOGET_PLANEINFO, (unsigned long)&pinfo) < 0)
    {
      HWTEST_FAIL("amoled", "ioctl failed: %d", errno);
      ret = -1;
      goto out;
    }

  HWTEST_INFO("amoled", "%ux%u bpp=%u stride=%u",
              vinfo.xres, vinfo.yres, pinfo.bpp, pinfo.stride);

  if (vinfo.xres != HWTEST_FB_WIDTH || vinfo.yres != HWTEST_FB_HEIGHT)
    {
      HWTEST_FAIL("amoled", "resolution mismatch");
      ret = -1;
      goto out;
    }

  HWTEST_PASS("amoled", "fb open OK, %ux%u, bpp=%u",
              vinfo.xres, vinfo.yres, pinfo.bpp);

  /* mmap 并画彩条 */

  fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
               MAP_SHARED | MAP_FILE, fd_fb, 0);
  if (fbmem == MAP_FAILED)
    {
      HWTEST_FAIL("amoled", "mmap failed: %d", errno);
      ret = -1;
      goto out;
    }

  draw_color_bars(fbmem, vinfo.xres, vinfo.yres, pinfo.stride);

  /* 关键：FBIO_UPDATE 推送到 LCD */

#ifdef CONFIG_FB_UPDATE
  {
    struct fb_area_s area = { 0, 0, vinfo.xres, vinfo.yres };
    if (ioctl(fd_fb, FBIO_UPDATE, (unsigned long)&area) < 0)
      {
        HWTEST_FAIL("amoled", "FBIO_UPDATE failed: %d", errno);
        ret = -1;
        goto out;
      }
  }
#endif

  HWTEST_PASS("amoled", "draw color bars OK (8 vertical stripes)");

  /* 等待触摸设备就绪（LCD 异步初始化） */

  for (retry = 0; retry < 10; retry++)
    {
      fd_touch = open(HWTEST_TOUCH_DEV, O_RDONLY);
      if (fd_touch >= 0) break;
      if (errno != ENOENT)
        {
          HWTEST_FAIL("amoled", "open %s failed: %d",
                      HWTEST_TOUCH_DEV, errno);
          ret = -1;
          goto out;
        }
      HWTEST_INFO("amoled", "waiting for touch device... (%d/10)", retry + 1);
      usleep(500000);
    }

  if (fd_touch < 0)
    {
      HWTEST_FAIL("amoled", "touch device not found after 5s");
      ret = -1;
      goto out;
    }

  HWTEST_INFO("amoled", "touch opened, please touch screen (10s timeout)");

  struct pollfd pfd = { fd_touch, POLLIN, 0 };
  if (poll(&pfd, 1, 10000) > 0)
    {
      struct touch_sample_s sample;
      read(fd_touch, &sample, sizeof(sample));
      HWTEST_PASS("amoled", "touch event at (%ld,%ld)",
                  (long)sample.point[0].x, (long)sample.point[0].y);
    }
  else
    {
      HWTEST_SKIP("amoled", "no touch event in 10s");
    }

out:
  if (fbmem && fbmem != MAP_FAILED) munmap(fbmem, pinfo.fblen);
  if (fd_fb >= 0) close(fd_fb);
  if (fd_touch >= 0) close(fd_touch);
  return ret;
}

/****************************************************************************
 * test_imu.c — 六轴 IMU (LSM6DS3TR-C) 验证
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <nuttx/sensors/lsm6dsl.h>
#include "hwtest.h"

#define IMU_N_SAMPLES  5
#define IMU_SAMPLE_DELAY 1

static int verify_sample(FAR const struct lsm6dsl_sensor_data_s *d, int idx)
{
  printf("  [%d] acc=(%d,%d,%d) mg  gyro=(%d,%d,%d) mdps  temp=%u ts=%u\n",
         idx, d->x_data, d->y_data, d->z_data,
         d->g_x_data, d->g_y_data, d->g_z_data,
         d->temperature, d->timestamp);

  int acc_mag = abs(d->x_data) + abs(d->y_data) + abs(d->z_data);
  if (acc_mag < 200 || acc_mag > 3000)
    {
      HWTEST_FAIL("imu", "sample[%d] acc magnitude %d out of range", idx,
                  acc_mag);
      return -1;
    }

  if (d->temperature < 15 || d->temperature > 50)
    {
      HWTEST_FAIL("imu", "sample[%d] temp=%u out of range", idx,
                  d->temperature);
      return -1;
    }

  return 0;
}

int test_imu(int argc, char *argv[])
{
  struct lsm6dsl_sensor_data_s data;
  FILE *sensor;
  int pass = 0, fail = 0, i, ret;

  printf("\n--- 测试 #2: 六轴 IMU (LSM6DS3TR-C) ---\n\n");

  sensor = fopen(HWTEST_IMU_DEV, "r");
  if (!sensor)
    {
      HWTEST_FAIL("imu", "open %s failed: %d", HWTEST_IMU_DEV, errno);
      return -1;
    }

  ret = ioctl(fileno(sensor), SNIOC_START, 0);
  if (ret < 0)
    {
      HWTEST_FAIL("imu", "SNIOC_START failed: %d", ret);
      goto out;
    }

  HWTEST_PASS("imu", "device opened, SNIOC_START OK");
  usleep(100000);

  for (i = 0; i < IMU_N_SAMPLES; i++)
    {
      ret = ioctl(fileno(sensor), SNIOC_LSM6DSLSENSORREAD,
                  (unsigned long)&data);
      if (ret < 0)
        {
          HWTEST_FAIL("imu", "read failed at [%d]: %d", i, ret);
          fail++;
          continue;
        }

      if (verify_sample(&data, i) == 0)
        pass++;
      else
        fail++;

      if (i < IMU_N_SAMPLES - 1) sleep(IMU_SAMPLE_DELAY);
    }

  if (fail == 0)
    HWTEST_PASS("imu", "%d/%d samples OK", pass, IMU_N_SAMPLES);
  else
    HWTEST_FAIL("imu", "%d/%d passed, %d failed", pass, IMU_N_SAMPLES, fail);

  ioctl(fileno(sensor), SNIOC_STOP, 0);

out:
  fclose(sensor);
  return fail > 0 ? -1 : 0;
}

/****************************************************************************
 * test_button.c — 功能按键 (KEY2) 验证
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <nuttx/input/buttons.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>
#include <poll.h>
#include "hwtest.h"

#define BTN_N_EVENTS    6
#define BTN_TIMEOUT_MS  15000

int test_button(int argc, char *argv[])
{
  btn_buttonset_t supported, sample;
  struct pollfd pfd;
  int fd, ret, i;
  int press = 0, release = 0;

  printf("\n--- 测试 #8: 功能按键 (KEY2) ---\n\n");

  fd = open(HWTEST_BTN_DEV, O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      HWTEST_FAIL("button", "open %s failed: %d", HWTEST_BTN_DEV, errno);
      return -1;
    }

  ret = ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported);
  if (ret < 0)
    {
      HWTEST_FAIL("button", "BTNIOC_SUPPORTED failed: %d", ret);
      close(fd);
      return -1;
    }

  HWTEST_INFO("button", "supported mask = 0x%02X", supported);
  HWTEST_PASS("button", "device opened, supported mask = 0x%02X", supported);

  HWTEST_INFO("button", "press KEY2 %d times (%ds timeout)",
              BTN_N_EVENTS / 2, BTN_TIMEOUT_MS / 1000);

  pfd.fd = fd;
  pfd.events = POLLIN;

  for (i = 0; i < BTN_N_EVENTS; i++)
    {
      ret = poll(&pfd, 1, BTN_TIMEOUT_MS);
      if (ret <= 0)
        {
          HWTEST_FAIL("button", "timeout at event %d", i);
          close(fd);
          return -1;
        }

      ret = read(fd, &sample, sizeof(sample));
      if (ret < (int)sizeof(sample))
        {
          HWTEST_FAIL("button", "read failed: %d", errno);
          close(fd);
          return -1;
        }

      if (sample & 0x01)
        { press++; HWTEST_INFO("button", "event[%d]: PRESSED", i); }
      else
        { release++; HWTEST_INFO("button", "event[%d]: RELEASED", i); }
    }

  if (press > 0 && release > 0)
    HWTEST_PASS("button", "KEY2 pressed %d, released %d", press, release);
  else if (press > 0)
    HWTEST_PASS("button", "KEY2 pressed %d", press);
  else
    {
      HWTEST_FAIL("button", "no press events captured");
      close(fd);
      return -1;
    }

  close(fd);
  return 0;
}

/****************************************************************************
 * test_rtc.c — RTC 实时时钟验证
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <nuttx/timers/rtc.h>
#include "hwtest.h"

static void print_time(FAR const char *tag, FAR const struct rtc_time *rt)
{
  printf("  %s: %04d-%02d-%02d %02d:%02d:%02d\n", tag,
         rt->tm_year + 1900, rt->tm_mon + 1, rt->tm_mday,
         rt->tm_hour, rt->tm_min, rt->tm_sec);
}

int test_rtc(int argc, char *argv[])
{
  struct rtc_time rt_set, rt_read, rt_after;
  int fd, ret, sec_before, sec_after;

  printf("\n--- 测试 #10: RTC 实时时钟 ---\n\n");

  fd = open(HWTEST_RTC_DEV, O_RDONLY);
  if (fd < 0)
    {
      HWTEST_FAIL("rtc", "open %s failed: %d", HWTEST_RTC_DEV, errno);
      return -1;
    }

  /* 读当前时间 */

  memset(&rt_read, 0, sizeof(rt_read));
  ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_read);
  print_time("current", &rt_read);

  /* 设置测试时间 */

  memset(&rt_set, 0, sizeof(rt_set));
  rt_set.tm_year = 2026 - 1900;
  rt_set.tm_mon  = 0;  /* January */
  rt_set.tm_mday = 1;
  rt_set.tm_hour = 12;
  rt_set.tm_min  = 0;
  rt_set.tm_sec  = 0;

  ret = ioctl(fd, RTC_SET_TIME, (unsigned long)&rt_set);
  if (ret < 0)
    {
      HWTEST_FAIL("rtc", "RTC_SET_TIME failed: %d", ret);
      close(fd);
      return -1;
    }

  print_time("set to", &rt_set);
  HWTEST_PASS("rtc", "set time to 2026-01-01 12:00:00");

  /* 读回验证 */

  usleep(100000);
  memset(&rt_read, 0, sizeof(rt_read));
  ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_read);
  print_time("readback", &rt_read);

  if (rt_read.tm_year != rt_set.tm_year ||
      rt_read.tm_mon  != rt_set.tm_mon ||
      rt_read.tm_mday != rt_set.tm_mday ||
      rt_read.tm_hour != rt_set.tm_hour ||
      rt_read.tm_min  != rt_set.tm_min)
    {
      HWTEST_FAIL("rtc", "read-back mismatch");
      close(fd);
      return -1;
    }

  /* 等 2 秒验证时间前进 */

  sec_before = rt_read.tm_hour * 3600 + rt_read.tm_min * 60 + rt_read.tm_sec;
  sleep(2);

  memset(&rt_after, 0, sizeof(rt_after));
  ioctl(fd, RTC_RD_TIME, (unsigned long)&rt_after);
  print_time("after 2s", &rt_after);

  sec_after = rt_after.tm_hour * 3600 + rt_after.tm_min * 60 + rt_after.tm_sec;

  if (sec_after > sec_before)
    HWTEST_PASS("rtc", "time advancing (+%ds in 2s)", sec_after - sec_before);
  else
    HWTEST_PASS("rtc", "read back OK, time consistent");

  HWTEST_INFO("rtc", "use 'date -s \"YYYY-MM-DD HH:MM:SS\"' to restore time");

  close(fd);
  return 0;
}

/****************************************************************************
 * test_rgbled.c — RGB LED (PWM) 验证
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <nuttx/timers/pwm.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include "hwtest.h"

int test_rgbled(int argc, char *argv[])
{
  struct pwm_info_s info;
  int fd, ret;
  static const uint8_t duty[] = { 0, 25, 50, 75, 100 };
  int i;

  printf("\n--- 测试 #6: RGB LED (PWM) ---\n\n");

  fd = open(HWTEST_PWM_DEV, O_RDONLY);
  if (fd < 0)
    {
      HWTEST_FAIL("rgbled", "open %s failed: %d", HWTEST_PWM_DEV, errno);
      return -1;
    }

  memset(&info, 0, sizeof(info));
  info.frequency = 800000;
  info.duty = 0;
  ret = ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
  if (ret < 0)
    {
      HWTEST_FAIL("rgbled", "PWM set failed: %d", ret);
      close(fd);
      return -1;
    }

  HWTEST_PASS("rgbled", "PWM open OK, freq=800kHz");

  ioctl(fd, PWMIOC_START, 0);

  HWTEST_INFO("rgbled", "brightness sweep: 0%% -> 100%% -> 0%%");

  for (i = 0; i < 5; i++)
    {
      info.duty = duty[i] * 10;
      ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
      printf("  duty = %d%%\n", duty[i]);
      usleep(500000);
    }

  for (i = 4; i >= 0; i--)
    {
      info.duty = duty[i] * 10;
      ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
      printf("  duty = %d%%\n", duty[i]);
      usleep(500000);
    }

  ioctl(fd, PWMIOC_STOP, 0);
  HWTEST_PASS("rgbled", "brightness sweep complete");

  close(fd);
  return 0;
}

/****************************************************************************
 * status_bar.h — LVGL 顶部 4px 状态色带组件
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#ifndef __STATUS_BAR_H
#define __STATUS_BAR_H

#include <lvgl.h>

/****************************************************************************
 * 状态枚举
 ****************************************************************************/

enum device_status
{
  STATUS_NORMAL,  /* 绿色，静态 */
  STATUS_NOTIFY,  /* 蓝色，闪烁 3 次后保持 */
  STATUS_ALERT,   /* 红色，呼吸循环 */
  STATUS_SLEEP    /* 隐藏（息屏） */
};

/****************************************************************************
 * 公开接口
 ****************************************************************************/

/**
 * 在屏幕顶部创建 4px 色带
 * @param parent 父对象（通常传 lv_screen_active()）
 */

void status_bar_init(lv_obj_t *parent);

/**
 * 切换状态（含动画管理）
 * @param s 目标状态
 */

void status_bar_set(enum device_status s);

/**
 * 确认告警：红 → 绿
 */

void status_bar_acknowledge(void);

/**
 * 隐藏色带（息屏用）
 */

void status_bar_hide(void);

/**
 * 显示色带（亮屏用）
 */

void status_bar_show(void);

/**
 * 获取当前状态
 */

enum device_status status_bar_get(void);

#endif /* __STATUS_BAR_H */

/****************************************************************************
 * status_bar.c — LVGL 顶部 4px 状态色带组件
 *
 * 实现说明：
 *   - 闪烁动画：lv_timer 驱动，500ms 周期，循环 3 次后停止
 *   - 呼吸动画：lv_anim 驱动透明度 30→255→30，2s 周期，无限循环
 *   - 状态切换时统一清理旧动画/timer，防止叠加泄漏
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include "status_bar.h"

/****************************************************************************
 * 颜色定义（RGB565 下可直接使用 lv_color_hex）
 ****************************************************************************/

#define COLOR_GREEN   lv_color_hex(0x00E676)  /* 正常运行 */
#define COLOR_BLUE    lv_color_hex(0x2979FF)  /* 提醒/通知 */
#define COLOR_RED     lv_color_hex(0xFF1744)  /* 告警 */
#define COLOR_BLACK   lv_color_hex(0x000000)  /* 闪烁灭色 */

#define BAR_HEIGHT    4       /* 色带高度 px */
#define BLINK_PERIOD  500     /* 闪烁周期 ms */
#define BLINK_REPEATS 3       /* 闪烁次数 */
#define BREATH_PERIOD 2000    /* 呼吸周期 ms */

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static lv_obj_t        *g_bar       = NULL;  /* 色带对象 */
static lv_timer_t      *g_blink_tm  = NULL;  /* 闪烁定时器 */
static lv_anim_t        g_breath_anim;       /* 呼吸动画 */
static enum device_status g_status   = STATUS_NORMAL;
static int              g_blink_count = 0;   /* 闪烁计数 */

/****************************************************************************
 * 闪烁定时器回调
 ****************************************************************************/

static void blink_timer_cb(lv_timer_t *timer)
{
  if (!g_bar) return;

  g_blink_count++;

  /* 奇数次灭，偶数次亮 */

  if (g_blink_count % 2 == 1)
    {
      lv_obj_set_style_bg_color(g_bar, COLOR_BLACK, 0);
    }
  else
    {
      lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);
    }

  /* 闪烁 3 次 = 6 次状态切换后停止，保持蓝色常亮 */

  if (g_blink_count >= BLINK_REPEATS * 2)
    {
      lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);
      lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
      lv_timer_delete(g_blink_tm);
      g_blink_tm = NULL;
    }
}

/****************************************************************************
 * 呼吸动画执行回调
 ****************************************************************************/

static void breath_exec_cb(void *var, int32_t value)
{
  lv_obj_set_style_opa((lv_obj_t *)var, (lv_opa_t)value, 0);
}

/****************************************************************************
 * 动画清理（切换状态前统一调用）
 ****************************************************************************/

static void anim_cleanup(void)
{
  /* 停止闪烁定时器 */

  if (g_blink_tm)
    {
      lv_timer_delete(g_blink_tm);
      g_blink_tm = NULL;
    }

  /* 删除呼吸动画 */

  lv_anim_delete(g_bar, breath_exec_cb);
  g_blink_count = 0;

  /* 恢复完全不透明 */

  if (g_bar)
    {
      lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
    }
}

/****************************************************************************
 * 公开接口实现
 ****************************************************************************/

void status_bar_init(lv_obj_t *parent)
{
  if (g_bar) return;  /* 防止重复初始化 */

  g_bar = lv_obj_create(parent);
  lv_obj_set_size(g_bar, LV_HOR_RES, BAR_HEIGHT);
  lv_obj_align(g_bar, LV_ALIGN_TOP_MID, 0, 0);

  /* 去掉默认边框、内边距、滚动条 */

  lv_obj_set_style_border_width(g_bar, 0, 0);
  lv_obj_set_style_pad_all(g_bar, 0, 0);
  lv_obj_set_style_radius(g_bar, 0, 0);
  lv_obj_remove_flag(g_bar, LV_OBJ_FLAG_SCROLLABLE);

  /* 初始颜色：绿色 */

  lv_obj_set_style_bg_color(g_bar, COLOR_GREEN, 0);
  lv_obj_set_style_bg_opa(g_bar, LV_OPA_COVER, 0);

  /* 置于最前 */

  lv_obj_move_foreground(g_bar);

  g_status = STATUS_NORMAL;
}

void status_bar_set(enum device_status s)
{
  if (!g_bar) return;
  if (s == g_status) return;  /* 避免重复设置 */

  /* 清理旧动画 */

  anim_cleanup();

  g_status = s;

  switch (s)
    {
      case STATUS_NORMAL:
        lv_obj_set_style_bg_color(g_bar, COLOR_GREEN, 0);
        lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
        break;

      case STATUS_NOTIFY:
        /* 蓝色闪烁 3 次后保持 */

        lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);
        lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
        g_blink_count = 0;
        g_blink_tm = lv_timer_create(blink_timer_cb, BLINK_PERIOD / 2, NULL);
        break;

      case STATUS_ALERT:
        /* 红色呼吸循环 */

        lv_obj_set_style_bg_color(g_bar, COLOR_RED, 0);
        lv_anim_init(&g_breath_anim);
        lv_anim_set_var(&g_breath_anim, g_bar);
        lv_anim_set_exec_cb(&g_breath_anim, breath_exec_cb);
        lv_anim_set_values(&g_breath_anim, LV_OPA_30, LV_OPA_COVER);
        lv_anim_set_duration(&g_breath_anim, BREATH_PERIOD / 2);
        lv_anim_set_playback_duration(&g_breath_anim, BREATH_PERIOD / 2);
        lv_anim_set_repeat_count(&g_breath_anim, LV_ANIM_REPEAT_INFINITE);
        lv_anim_set_path_cb(&g_breath_anim, lv_anim_path_ease_in_out);
        lv_anim_start(&g_breath_anim);
        break;

      case STATUS_SLEEP:
        lv_obj_add_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
        break;
    }
}

void status_bar_acknowledge(void)
{
  if (g_status == STATUS_ALERT)
    {
      status_bar_set(STATUS_NORMAL);
    }
}

void status_bar_hide(void)
{
  if (g_bar)
    {
      lv_obj_add_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
    }
}

void status_bar_show(void)
{
  if (g_bar)
    {
      lv_obj_remove_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
    }
}

enum device_status status_bar_get(void)
{
  return g_status;
}

