/****************************************************************************
 * motor.c — 马达震动模式封装
 *
 * 驱动接口：/dev/pwm0 (GPTIM1_CH3)
 * 控制方式：PWM 占空比 100% = 震动，0% = 停止
 *
 * 非阻塞实现：使用 lv_timer 驱动震动序列状态机
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <nuttx/timers/pwm.h>
#include <nuttx/fixedmath.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <lvgl.h>
#include "motor.h"

/****************************************************************************
 * 私有定义
 ****************************************************************************/

#define MOTOR_PWM_DEV     "/dev/pwm0"
#define MOTOR_PWM_FREQ    200     /* 震动马达典型频率 200Hz */
#define MOTOR_ON_DUTY     100     /* 100% 占空比 = 全速震动 */
#define MOTOR_OFF_DUTY    0       /* 0% = 停止 */

/* 百分比转 ub16_t 固定点数 */

#define PCT_TO_UB16(pct) \
  ((pct) >= 100 ? ub16MAX : b16divi(uitoub16(pct) - 1, 100))

/****************************************************************************
 * 震动序列状态机
 ****************************************************************************/

enum motor_seq_state
{
  SEQ_IDLE = 0,
  SEQ_NOTIFY_ON,      /* 短震：开 */
  SEQ_NOTIFY_OFF,     /* 短震：关（等待结束） */
  SEQ_ALERT_ON1,      /* 三短震第1次开 */
  SEQ_ALERT_OFF1,     /* 三短震第1次关 */
  SEQ_ALERT_ON2,      /* 三短震第2次开 */
  SEQ_ALERT_OFF2,     /* 三短震第2次关 */
  SEQ_ALERT_ON3,      /* 三短震第3次开 */
  SEQ_ALERT_OFF3,     /* 三短震第3次关 */
  SEQ_WAKEUP_ON,      /* 唤醒震：开 */
  SEQ_WAKEUP_OFF      /* 唤醒震：关 */
};

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static int              g_pwm_fd   = -1;
static lv_timer_t      *g_seq_tm   = NULL;   /* 序列定时器 */
static enum motor_seq_state g_seq_state = SEQ_IDLE;

/****************************************************************************
 * PWM 底层操作
 ****************************************************************************/

static int pwm_set_duty(uint8_t percent)
{
  struct pwm_info_s info;

  if (g_pwm_fd < 0) return -1;

  memset(&info, 0, sizeof(info));
  info.frequency = MOTOR_PWM_FREQ;
  info.channels[0].channel = 1;
  info.channels[0].duty = PCT_TO_UB16(percent);

  return ioctl(g_pwm_fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
}

static int pwm_start(void)
{
  if (g_pwm_fd < 0) return -1;
  return ioctl(g_pwm_fd, PWMIOC_START, 0);
}

static int pwm_stop(void)
{
  if (g_pwm_fd < 0) return -1;
  return ioctl(g_pwm_fd, PWMIOC_STOP, 0);
}

/****************************************************************************
 * 序列定时器回调（非阻塞状态机）
 ****************************************************************************/

static void seq_timer_cb(lv_timer_t *timer)
{
  switch (g_seq_state)
    {
      /* ── 短震 200ms ───────────────────────────────────── */

      case SEQ_NOTIFY_ON:
        pwm_set_duty(MOTOR_ON_DUTY);
        pwm_start();
        g_seq_state = SEQ_NOTIFY_OFF;
        lv_timer_set_period(g_seq_tm, 200);
        break;

      case SEQ_NOTIFY_OFF:
        pwm_stop();
        pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm);
        g_seq_tm = NULL;
        break;

      /* ── 三短震 200ms×3 间隔 150ms ────────────────────── */

      case SEQ_ALERT_ON1:
        pwm_set_duty(MOTOR_ON_DUTY);
        pwm_start();
        g_seq_state = SEQ_ALERT_OFF1;
        lv_timer_set_period(g_seq_tm, 200);
        break;

      case SEQ_ALERT_OFF1:
        pwm_stop();
        g_seq_state = SEQ_ALERT_ON2;
        lv_timer_set_period(g_seq_tm, 150);
        break;

      case SEQ_ALERT_ON2:
        pwm_set_duty(MOTOR_ON_DUTY);
        pwm_start();
        g_seq_state = SEQ_ALERT_OFF2;
        lv_timer_set_period(g_seq_tm, 200);
        break;

      case SEQ_ALERT_OFF2:
        pwm_stop();
        g_seq_state = SEQ_ALERT_ON3;
        lv_timer_set_period(g_seq_tm, 150);
        break;

      case SEQ_ALERT_ON3:
        pwm_set_duty(MOTOR_ON_DUTY);
        pwm_start();
        g_seq_state = SEQ_ALERT_OFF3;
        lv_timer_set_period(g_seq_tm, 200);
        break;

      case SEQ_ALERT_OFF3:
        pwm_stop();
        pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm);
        g_seq_tm = NULL;
        break;

      /* ── 唤醒震 100ms ─────────────────────────────────── */

      case SEQ_WAKEUP_ON:
        pwm_set_duty(MOTOR_ON_DUTY);
        pwm_start();
        g_seq_state = SEQ_WAKEUP_OFF;
        lv_timer_set_period(g_seq_tm, 100);
        break;

      case SEQ_WAKEUP_OFF:
        pwm_stop();
        pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm);
        g_seq_tm = NULL;
        break;

      default:
        break;
    }
}

/****************************************************************************
 * 停止当前序列
 ****************************************************************************/

static void seq_stop(void)
{
  if (g_seq_tm)
    {
      lv_timer_delete(g_seq_tm);
      g_seq_tm = NULL;
    }

  pwm_stop();
  pwm_set_duty(MOTOR_OFF_DUTY);
  g_seq_state = SEQ_IDLE;
}

/****************************************************************************
 * 启动序列
 ****************************************************************************/

static void seq_start(enum motor_seq_state initial)
{
  seq_stop();
  g_seq_state = initial;
  g_seq_tm = lv_timer_create(seq_timer_cb, 1, NULL);  /* 立即触发首次 */
}

/****************************************************************************
 * 公开接口实现
 ****************************************************************************/

void motor_init(void)
{
  if (g_pwm_fd >= 0) return;

  g_pwm_fd = open(MOTOR_PWM_DEV, O_RDONLY);
  if (g_pwm_fd < 0)
    {
      printf("[motor] open %s failed: %d\n", MOTOR_PWM_DEV, errno);
      return;
    }

  pwm_set_duty(MOTOR_OFF_DUTY);
  printf("[motor] initialized on %s\n", MOTOR_PWM_DEV);
}

void motor_on(void)
{
  seq_stop();
  pwm_set_duty(MOTOR_ON_DUTY);
  pwm_start();
}

void motor_off(void)
{
  seq_stop();
}

void motor_notify(void)
{
  seq_start(SEQ_NOTIFY_ON);
}

void motor_alert(void)
{
  seq_start(SEQ_ALERT_ON1);
}

void motor_wakeup(void)
{
  seq_start(SEQ_WAKEUP_ON);
}

void motor_deinit(void)
{
  seq_stop();
  if (g_pwm_fd >= 0)
    {
      close(g_pwm_fd);
      g_pwm_fd = -1;
    }
}

