#ifndef __DEVICE_STATUS_H
#define __DEVICE_STATUS_H

#include <lvgl.h>
#include "status_bar.h"

/**
 * 初始化状态系统（色带 + 马达）
 * @param screen 屏幕对象（通常传 lv_screen_active()）
 */

void device_status_init(lv_obj_t *screen);

/**
 * 设置设备状态（色带 + 马达联动）
 * @param s 目标状态
 */

void device_status_set(enum device_status s);

/**
 * 获取当前状态
 */

enum device_status device_status_get(void);

