/****************************************************************************
 * device_status.c — 统一状态入口
 *
 * 联动 status_bar（色带动画）和 motor（震动模式）
 * 维护全局状态变量，避免重复触发
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include "device_status.h"
#include "status_bar.h"
#include "motor.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static enum device_status g_current = STATUS_NORMAL;

/****************************************************************************
 * 公开接口实现
 ****************************************************************************/

void device_status_init(lv_obj_t *screen)
{
  status_bar_init(screen);
  motor_init();
  g_current = STATUS_NORMAL;
}

void device_status_set(enum device_status s)
{
  if (s == g_current) return;  /* 避免重复触发 */

  g_current = s;

  /* 色带动画 */

  status_bar_set(s);

  /* 马达震动联动 */

  switch (s)
    {
      case STATUS_NORMAL:
        motor_off();
        break;

      case STATUS_NOTIFY:
        motor_notify();
        break;

      case STATUS_ALERT:
        motor_alert();
        break;

      case STATUS_SLEEP:
        motor_off();
        break;
    }
}

enum device_status device_status_get(void)
{
  return g_current;
}

