 * test_status_page.c — 状态指示系统测试页面
 *
 * 5 个按钮：Normal / Notify / Alert / ACK / Sleep-Wake
 * 垂直排列，120×50，间距 15px
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <lvgl.h>
#include "status_bar.h"
#include "motor.h"
#include "device_status.h"

/****************************************************************************
 * 按钮回调
 ****************************************************************************/

static void btn_normal_cb(lv_event_t *e)
{
  LV_UNUSED(e);
  device_status_set(STATUS_NORMAL);
}

static void btn_notify_cb(lv_event_t *e)
{
  LV_UNUSED(e);
  device_status_set(STATUS_NOTIFY);
}

static void btn_alert_cb(lv_event_t *e)
{
  LV_UNUSED(e);
  device_status_set(STATUS_ALERT);
}

static void btn_ack_cb(lv_event_t *e)
{
  LV_UNUSED(e);
  status_bar_acknowledge();
  motor_off();
}

static bool g_sleeping = false;

static void btn_sleep_cb(lv_event_t *e)
{
  LV_UNUSED(e);

  g_sleeping = !g_sleeping;

  if (g_sleeping)
    {
      device_status_set(STATUS_SLEEP);
      motor_wakeup();
    }
  else
    {
      status_bar_show();
      device_status_set(STATUS_NORMAL);
    }
}

/****************************************************************************
 * 创建测试页面
 ****************************************************************************/

static lv_obj_t *create_btn(lv_obj_t *parent, const char *text,
                             lv_event_cb_t cb)
{
  lv_obj_t *btn = lv_btn_create(parent);
  lv_obj_set_size(btn, 120, 50);

  lv_obj_t *label = lv_label_create(btn);
  lv_label_set_text(label, text);
  lv_obj_center(label);

  lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, NULL);
  return btn;
}

void test_status_page_create(void)
{
  lv_obj_t *scr = lv_screen_active();

  /* 初始化状态系统 */

  device_status_init(scr);

  /* 创建按钮容器（居中排列） */

  lv_obj_t *cont = lv_obj_create(scr);
  lv_obj_set_size(cont, 160, 420);
  lv_obj_align(cont, LV_ALIGN_CENTER, 0, 20);
  lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(cont, 15, 0);
  lv_obj_set_style_bg_opa(cont, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(cont, 0, 0);

  /* 创建 5 个按钮 */

  create_btn(cont, "Normal", btn_normal_cb);
  create_btn(cont, "Notify", btn_notify_cb);
  create_btn(cont, "Alert", btn_alert_cb);
  create_btn(cont, "ACK", btn_ack_cb);
  create_btn(cont, "Sleep/Wake", btn_sleep_cb);
}

