/****************************************************************************
 * status_bar.h — LVGL 顶部 4px 状态色带组件
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#ifndef __STATUS_BAR_H
#define __STATUS_BAR_H

#include <lvgl.h>

enum device_status
{
  STATUS_NORMAL,  /* 绿色，静态 */
  STATUS_NOTIFY,  /* 蓝色，闪烁 3 次后保持 */
  STATUS_ALERT,   /* 红色，呼吸循环 */
  STATUS_SLEEP    /* 隐藏（息屏） */
};

void status_bar_init(lv_obj_t *parent);
void status_bar_set(enum device_status s);
void status_bar_acknowledge(void);
void status_bar_hide(void);
void status_bar_show(void);
enum device_status status_bar_get(void);

#endif

/****************************************************************************
 * status_bar.c — LVGL 顶部 4px 状态色带组件
 *
 * 闪烁：lv_timer 驱动，500ms 周期，3 次后停止
 * 呼吸：lv_anim 驱动 opa 30→255→30，2s 周期，无限循环
 * 状态切换时统一清理旧动画/timer
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include "status_bar.h"

#define COLOR_GREEN   lv_color_hex(0x00E676)
#define COLOR_BLUE    lv_color_hex(0x2979FF)
#define COLOR_RED     lv_color_hex(0xFF1744)
#define COLOR_BLACK   lv_color_hex(0x000000)

#define BAR_HEIGHT    4
#define BLINK_PERIOD  500
#define BLINK_REPEATS 3
#define BREATH_PERIOD 2000

static lv_obj_t        *g_bar       = NULL;
static lv_timer_t      *g_blink_tm  = NULL;
static lv_anim_t        g_breath_anim;
static enum device_status g_status   = STATUS_NORMAL;
static int              g_blink_count = 0;

/* ── 闪烁定时器回调 ──────────────────────────────────────────────── */

static void blink_timer_cb(lv_timer_t *timer)
{
  if (!g_bar) return;

  g_blink_count++;

  if (g_blink_count % 2 == 1)
    lv_obj_set_style_bg_color(g_bar, COLOR_BLACK, 0);
  else
    lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);

  /* 闪烁 3 次 = 6 次切换后停止，保持蓝色常亮 */

  if (g_blink_count >= BLINK_REPEATS * 2)
    {
      lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);
      lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
      lv_timer_delete(g_blink_tm);
      g_blink_tm = NULL;
    }
}

/* ── 呼吸动画执行回调 ────────────────────────────────────────────── */

static void breath_exec_cb(void *var, int32_t value)
{
  lv_obj_set_style_opa((lv_obj_t *)var, (lv_opa_t)value, 0);
}

/* ── 动画清理 ─────────────────────────────────────────────────────── */

static void anim_cleanup(void)
{
  if (g_blink_tm)
    {
      lv_timer_delete(g_blink_tm);
      g_blink_tm = NULL;
    }

  lv_anim_delete(g_bar, breath_exec_cb);
  g_blink_count = 0;

  if (g_bar)
    lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
}

/* ── 公开接口 ─────────────────────────────────────────────────────── */

void status_bar_init(lv_obj_t *parent)
{
  if (g_bar) return;

  g_bar = lv_obj_create(parent);
  lv_obj_set_size(g_bar, LV_HOR_RES, BAR_HEIGHT);
  lv_obj_align(g_bar, LV_ALIGN_TOP_MID, 0, 0);

  lv_obj_set_style_border_width(g_bar, 0, 0);
  lv_obj_set_style_pad_all(g_bar, 0, 0);
  lv_obj_set_style_radius(g_bar, 0, 0);
  lv_obj_remove_flag(g_bar, LV_OBJ_FLAG_SCROLLABLE);

  lv_obj_set_style_bg_color(g_bar, COLOR_GREEN, 0);
  lv_obj_set_style_bg_opa(g_bar, LV_OPA_COVER, 0);
  lv_obj_move_foreground(g_bar);

  g_status = STATUS_NORMAL;
}

void status_bar_set(enum device_status s)
{
  if (!g_bar) return;
  if (s == g_status) return;

  anim_cleanup();
  g_status = s;

  switch (s)
    {
      case STATUS_NORMAL:
        lv_obj_set_style_bg_color(g_bar, COLOR_GREEN, 0);
        lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
        break;

      case STATUS_NOTIFY:
        lv_obj_set_style_bg_color(g_bar, COLOR_BLUE, 0);
        lv_obj_set_style_opa(g_bar, LV_OPA_COVER, 0);
        g_blink_count = 0;
        g_blink_tm = lv_timer_create(blink_timer_cb, BLINK_PERIOD / 2, NULL);
        break;

      case STATUS_ALERT:
        lv_obj_set_style_bg_color(g_bar, COLOR_RED, 0);
        lv_anim_init(&g_breath_anim);
        lv_anim_set_var(&g_breath_anim, g_bar);
        lv_anim_set_exec_cb(&g_breath_anim, breath_exec_cb);
        lv_anim_set_values(&g_breath_anim, LV_OPA_30, LV_OPA_COVER);
        lv_anim_set_duration(&g_breath_anim, BREATH_PERIOD / 2);
        lv_anim_set_playback_duration(&g_breath_anim, BREATH_PERIOD / 2);
        lv_anim_set_repeat_count(&g_breath_anim, LV_ANIM_REPEAT_INFINITE);
        lv_anim_set_path_cb(&g_breath_anim, lv_anim_path_ease_in_out);
        lv_anim_start(&g_breath_anim);
        break;

      case STATUS_SLEEP:
        lv_obj_add_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
        break;
    }
}

void status_bar_acknowledge(void)
{
  if (g_status == STATUS_ALERT)
    status_bar_set(STATUS_NORMAL);
}

void status_bar_hide(void)
{
  if (g_bar)
    lv_obj_add_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
}

void status_bar_show(void)
{
  if (g_bar)
    lv_obj_remove_flag(g_bar, LV_OBJ_FLAG_HIDDEN);
}

enum device_status status_bar_get(void)
{
  return g_status;
}

/****************************************************************************
 * motor.c — 马达震动模式封装
 *
 * 驱动接口：/dev/pwm0 (GPTIM1_CH3)
 * 非阻塞：lv_timer 驱动震动序列状态机
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <nuttx/timers/pwm.h>
#include <fixedmath.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <lvgl.h>
#include "motor.h"

#define MOTOR_PWM_DEV   "/dev/pwm0"
#define MOTOR_PWM_FREQ  200
#define MOTOR_ON_DUTY   100
#define MOTOR_OFF_DUTY  0

/* 百分比转 ub16_t：100% → 0xFFFF，0% → 0 */

#define PCT_TO_UB16(p)  ((p) >= 100 ? ub16MAX : b16divi(uitoub16(p) - 1, 100))

/* ── 震动序列状态机 ──────────────────────────────────────────────── */

enum motor_seq_state
{
  SEQ_IDLE = 0,
  SEQ_NOTIFY_ON,   SEQ_NOTIFY_OFF,
  SEQ_ALERT_ON1,   SEQ_ALERT_OFF1,
  SEQ_ALERT_ON2,   SEQ_ALERT_OFF2,
  SEQ_ALERT_ON3,   SEQ_ALERT_OFF3,
  SEQ_WAKEUP_ON,   SEQ_WAKEUP_OFF
};

static int              g_pwm_fd = -1;
static lv_timer_t      *g_seq_tm = NULL;
static enum motor_seq_state g_seq_state = SEQ_IDLE;

/* ── PWM 底层操作 ────────────────────────────────────────────────── */

static int pwm_set_duty(uint8_t percent)
{
  struct pwm_info_s info;
  if (g_pwm_fd < 0) return -1;

  memset(&info, 0, sizeof(info));
  info.frequency = MOTOR_PWM_FREQ;
  info.duty = PCT_TO_UB16(percent);

  return ioctl(g_pwm_fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
}

static int pwm_start(void)
{
  return g_pwm_fd >= 0 ? ioctl(g_pwm_fd, PWMIOC_START, 0) : -1;
}

static int pwm_stop(void)
{
  return g_pwm_fd >= 0 ? ioctl(g_pwm_fd, PWMIOC_STOP, 0) : -1;
}

/* ── 序列定时器回调 ──────────────────────────────────────────────── */

static void seq_timer_cb(lv_timer_t *timer)
{
  switch (g_seq_state)
    {
      case SEQ_NOTIFY_ON:
        pwm_set_duty(MOTOR_ON_DUTY); pwm_start();
        g_seq_state = SEQ_NOTIFY_OFF;
        lv_timer_set_period(g_seq_tm, 200);
        break;
      case SEQ_NOTIFY_OFF:
        pwm_stop(); pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm); g_seq_tm = NULL;
        break;

      case SEQ_ALERT_ON1:
        pwm_set_duty(MOTOR_ON_DUTY); pwm_start();
        g_seq_state = SEQ_ALERT_OFF1;
        lv_timer_set_period(g_seq_tm, 200);
        break;
      case SEQ_ALERT_OFF1:
        pwm_stop();
        g_seq_state = SEQ_ALERT_ON2;
        lv_timer_set_period(g_seq_tm, 150);
        break;
      case SEQ_ALERT_ON2:
        pwm_set_duty(MOTOR_ON_DUTY); pwm_start();
        g_seq_state = SEQ_ALERT_OFF2;
        lv_timer_set_period(g_seq_tm, 200);
        break;
      case SEQ_ALERT_OFF2:
        pwm_stop();
        g_seq_state = SEQ_ALERT_ON3;
        lv_timer_set_period(g_seq_tm, 150);
        break;
      case SEQ_ALERT_ON3:
        pwm_set_duty(MOTOR_ON_DUTY); pwm_start();
        g_seq_state = SEQ_ALERT_OFF3;
        lv_timer_set_period(g_seq_tm, 200);
        break;
      case SEQ_ALERT_OFF3:
        pwm_stop(); pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm); g_seq_tm = NULL;
        break;

      case SEQ_WAKEUP_ON:
        pwm_set_duty(MOTOR_ON_DUTY); pwm_start();
        g_seq_state = SEQ_WAKEUP_OFF;
        lv_timer_set_period(g_seq_tm, 100);
        break;
      case SEQ_WAKEUP_OFF:
        pwm_stop(); pwm_set_duty(MOTOR_OFF_DUTY);
        g_seq_state = SEQ_IDLE;
        lv_timer_delete(g_seq_tm); g_seq_tm = NULL;
        break;

      default: break;
    }
}

static void seq_stop(void)
{
  if (g_seq_tm)
    {
      lv_timer_delete(g_seq_tm);
      g_seq_tm = NULL;
    }
  pwm_stop();
  pwm_set_duty(MOTOR_OFF_DUTY);
  g_seq_state = SEQ_IDLE;
}

static void seq_start(enum motor_seq_state initial)
{
  seq_stop();
  g_seq_state = initial;
  g_seq_tm = lv_timer_create(seq_timer_cb, 1, NULL);
}

/* ── 公开接口 ─────────────────────────────────────────────────────── */

void motor_init(void)
{
  if (g_pwm_fd >= 0) return;
  g_pwm_fd = open(MOTOR_PWM_DEV, O_RDONLY);
  if (g_pwm_fd < 0)
    printf("[motor] open %s failed: %d\n", MOTOR_PWM_DEV, errno);
  else
    {
      pwm_set_duty(MOTOR_OFF_DUTY);
      printf("[motor] initialized on %s\n", MOTOR_PWM_DEV);
    }
}

void motor_on(void)     { seq_stop(); pwm_set_duty(MOTOR_ON_DUTY); pwm_start(); }
void motor_off(void)    { seq_stop(); }
void motor_notify(void) { seq_start(SEQ_NOTIFY_ON); }
void motor_alert(void)  { seq_start(SEQ_ALERT_ON1); }
void motor_wakeup(void) { seq_start(SEQ_WAKEUP_ON); }

void motor_deinit(void)
{
  seq_stop();
  if (g_pwm_fd >= 0) { close(g_pwm_fd); g_pwm_fd = -1; }
}

