/****************************************************************************
 * status_indicator_main.c — 状态指示系统 NSH 入口
 *
 * 使用 framebuffer API 直接操作屏幕，不依赖 LVGL 初始化
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <nuttx/video/fb.h>

#include "status_bar.h"
#include "motor.h"
#include "device_status.h"

/****************************************************************************
 * 全局 framebuffer 状态
 ****************************************************************************/

static int          g_fb_fd   = -1;
static FAR uint16_t *g_fbmem  = NULL;
static uint32_t     g_stride  = 0;
static uint32_t     g_xres    = 0;
static uint32_t     g_yres    = 0;

/****************************************************************************
 * framebuffer 初始化
 ****************************************************************************/

static int fb_init(void)
{
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;

  g_fb_fd = open("/dev/fb0", O_RDWR);
  if (g_fb_fd < 0)
    {
      printf("ERROR: open /dev/fb0 failed\n");
      return -1;
    }

  if (ioctl(g_fb_fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo) < 0 ||
      ioctl(g_fb_fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo) < 0)
    {
      printf("ERROR: FBIOGET failed\n");
      close(g_fb_fd);
      g_fb_fd = -1;
      return -1;
    }

  g_xres   = vinfo.xres;
  g_yres   = vinfo.yres;
  g_stride = pinfo.stride;

  g_fbmem = (FAR uint16_t *)mmap(NULL, pinfo.fblen,
                                  PROT_READ | PROT_WRITE,
                                  MAP_SHARED | MAP_FILE, g_fb_fd, 0);
  if (g_fbmem == MAP_FAILED)
    {
      printf("ERROR: mmap failed\n");
      close(g_fb_fd);
      g_fb_fd = -1;
      g_fbmem = NULL;
      return -1;
    }

  printf("FB: %lux%lu bpp=%u stride=%lu\n",
         (unsigned long)g_xres, (unsigned long)g_yres,
         pinfo.bpp, (unsigned long)g_stride);

  return 0;
}

/****************************************************************************
 * 刷新屏幕指定区域
 ****************************************************************************/

static void fb_update(uint16_t x, uint16_t y, uint16_t w, uint16_t h)
{
#ifdef CONFIG_FB_UPDATE
  struct fb_area_s area = { x, y, w, h };
  if (g_fb_fd >= 0)
    ioctl(g_fb_fd, FBIO_UPDATE, (unsigned long)&area);
#endif
}

/****************************************************************************
 * 清屏为黑色
 ****************************************************************************/

static void fb_clear(void)
{
  if (!g_fbmem) return;
  uint32_t total = (g_stride / 2) * g_yres;
  for (uint32_t i = 0; i < total; i++)
    g_fbmem[i] = 0x0000;
  fb_update(0, 0, g_xres, g_yres);
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  printf("=== Status Indicator (Team 307) ===\n");
  printf("Frame buffer mode (no LVGL)\n\n");

  /* 初始化 framebuffer */

  if (fb_init() < 0)
    {
      printf("ERROR: framebuffer init failed\n");
      return -1;
    }

  /* 清屏 */

  fb_clear();

  /* 初始化状态系统（传入 fb 参数） */

  status_bar_init_fb(g_fbmem, g_xres, g_yres, g_stride, g_fb_fd);
  motor_init();
  device_status_set(STATUS_NORMAL);

  printf("\nStatus indicator started.\n");
  printf("Framebuffer: %lux%lu\n", (unsigned long)g_xres, (unsigned long)g_yres);
  printf("Use 'status_bar_set N/O/A/S' to test (N=Normal O=Notify A=Alert S=Sleep)\n");

  /* 简单交互循环 */

  char cmd[32];
  while (1)
    {
      printf("status> ");
      fflush(stdout);

      if (fgets(cmd, sizeof(cmd), stdin) == NULL)
        break;

      switch (cmd[0])
        {
          case 'n': case 'N':
            device_status_set(STATUS_NORMAL);
            printf("-> Normal\n");
            break;
          case 'o': case 'O':
            device_status_set(STATUS_NOTIFY);
            printf("-> Notify\n");
            break;
          case 'a': case 'A':
            device_status_set(STATUS_ALERT);
            printf("-> Alert\n");
            break;
          case 's': case 'S':
            status_bar_acknowledge();
            device_status_set(STATUS_SLEEP);
            printf("-> Sleep\n");
            break;
          case 'w': case 'W':
            status_bar_show();
            device_status_set(STATUS_NORMAL);
            motor_wakeup();
            printf("-> Wakeup\n");
            break;
          case 'q': case 'Q':
            goto out;
          default:
            printf("Commands: N=Normal O=Notify A=Alert S=Sleep W=Wakeup Q=Quit\n");
            break;
        }
    }

out:
  fb_clear();
  if (g_fbmem) munmap(g_fbmem, g_stride * g_yres);
  if (g_fb_fd >= 0) close(g_fb_fd);
  motor_deinit();
  printf("Bye.\n");
  return 0;
}

/****************************************************************************
 * status_bar.h — 顶部 4px 状态色带组件（framebuffer 直绘版）
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#ifndef __STATUS_BAR_H
#define __STATUS_BAR_H

#include <stdint.h>

enum device_status
{
  STATUS_NORMAL,  /* 绿色，静态 */
  STATUS_NOTIFY,  /* 蓝色，闪烁 3 次后保持 */
  STATUS_ALERT,   /* 红色，呼吸循环 */
  STATUS_SLEEP    /* 隐藏（息屏） */
};

/**
 * 初始化色带（framebuffer 模式）
 * @param fbmem   mmap 后的 framebuffer 地址
 * @param xres    屏幕宽度
 * @param yres    屏幕高度
 * @param stride  行字节数
 * @param fb_fd   framebuffer 设备 fd（用于 FBIO_UPDATE）
 */

void status_bar_init_fb(uint16_t *fbmem, uint32_t xres, uint32_t yres,
                        uint32_t stride, int fb_fd);

void status_bar_set(enum device_status s);
void status_bar_acknowledge(void);
void status_bar_hide(void);
void status_bar_show(void);
enum device_status status_bar_get(void);

#endif

/****************************************************************************
 * status_bar.c — 顶部 4px 状态色带（framebuffer 直绘版）
 *
 * 实现：
 *   - 直接写 framebuffer 内存 + FBIO_UPDATE 刷新
 *   - 闪烁/呼吸动画用后台线程 + usleep 驱动
 *   - 状态切换时终止旧线程再启动新线程
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <nuttx/video/fb.h>

#include "status_bar.h"

/****************************************************************************
 * 颜色定义（RGB565）
 ****************************************************************************/

#define RGB565(r, g, b) \
  (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | ((b) >> 3))

#define COLOR_GREEN   RGB565(0x00, 0xE6, 0x76)  /* #00E676 */
#define COLOR_BLUE    RGB565(0x29, 0x79, 0xFF)  /* #2979FF */
#define COLOR_RED     RGB565(0xFF, 0x17, 0x44)  /* #FF1744 */
#define COLOR_BLACK   0x0000

#define BAR_HEIGHT    4

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static uint16_t        *g_fbmem  = NULL;
static uint32_t         g_xres   = 0;
static uint32_t         g_stride = 0;  /* 字节数 */
static int              g_fb_fd  = -1;

static enum device_status g_status = STATUS_NORMAL;
static volatile int     g_running = 0;   /* 动画线程运行标志 */
static pthread_t        g_anim_thread;
static int              g_visible = 1;

/****************************************************************************
 * 绘制色带区域
 ****************************************************************************/

static void draw_bar(uint16_t color)
{
  if (!g_fbmem || !g_visible) return;

  uint32_t stride_px = g_stride / 2;
  for (int y = 0; y < BAR_HEIGHT; y++)
    {
      uint16_t *row = g_fbmem + y * stride_px;
      for (uint32_t x = 0; x < g_xres; x++)
        {
          row[x] = color;
        }
    }

  /* 刷新色带区域 */

#ifdef CONFIG_FB_UPDATE
  if (g_fb_fd >= 0)
    {
      struct fb_area_s area = { 0, 0, g_xres, BAR_HEIGHT };
      ioctl(g_fb_fd, FBIO_UPDATE, (unsigned long)&area);
    }
#endif
}

/****************************************************************************
 * 设置透明度模拟（通过混合黑色实现）
 ****************************************************************************/

static uint16_t blend_color(uint16_t color, uint8_t opacity)
{
  if (opacity >= 255) return color;
  if (opacity == 0)   return COLOR_BLACK;

  /* 分离 RGB565 通道 */

  uint8_t r = ((color >> 11) & 0x1F) * 8;
  uint8_t g = ((color >> 5)  & 0x3F) * 4;
  uint8_t b = (color & 0x1F) * 8;

  /* 按 opacity 混合 */

  r = (uint8_t)((r * opacity) / 255);
  g = (uint8_t)((g * opacity) / 255);
  b = (uint8_t)((b * opacity) / 255);

  return RGB565(r, g, b);
}

/****************************************************************************
 * 动画线程函数
 ****************************************************************************/

static void *blink_thread(void *arg)
{
  LV_UNUSED(arg);
  int count = 0;

  while (g_running && count < 6)  /* 3 次闪烁 = 6 次切换 */
    {
      if (count % 2 == 0)
        draw_bar(COLOR_BLACK);
      else
        draw_bar(COLOR_BLUE);

      count++;
      usleep(250000);  /* 250ms */
    }

  /* 闪烁结束，保持蓝色 */

  if (g_running)
    draw_bar(COLOR_BLUE);

  g_running = 0;
  return NULL;
}

static void *breath_thread(void *arg)
{
  LV_UNUSED(arg);
  int opa = 30;
  int direction = 1;  /* 1=渐亮, -1=渐暗 */

  while (g_running)
    {
      uint16_t blended = blend_color(COLOR_RED, (uint8_t)opa);
      draw_bar(blended);

      opa += direction * 5;
      if (opa >= 255) { opa = 255; direction = -1; }
      if (opa <= 30)  { opa = 30;  direction = 1;  }

      usleep(20000);  /* 20ms 步进，100 步 = 2s 周期 */
    }

  g_running = 0;
  return NULL;
}

/****************************************************************************
 * 停止当前动画
 ****************************************************************************/

static void anim_stop(void)
{
  if (g_running)
    {
      g_running = 0;
      pthread_join(g_anim_thread, NULL);
    }
}

/****************************************************************************
 * 公开接口
 ****************************************************************************/

void status_bar_init_fb(uint16_t *fbmem, uint32_t xres, uint32_t yres,
                        uint32_t stride, int fb_fd)
{
  g_fbmem  = fbmem;
  g_xres   = xres;
  g_stride = stride;
  g_fb_fd  = fb_fd;
  g_status = STATUS_NORMAL;
  g_visible = 1;

  draw_bar(COLOR_GREEN);
}

void status_bar_set(enum device_status s)
{
  if (s == g_status) return;

  anim_stop();
  g_status = s;

  switch (s)
    {
      case STATUS_NORMAL:
        draw_bar(COLOR_GREEN);
        break;

      case STATUS_NOTIFY:
        draw_bar(COLOR_BLUE);
        g_running = 1;
        pthread_create(&g_anim_thread, NULL, blink_thread, NULL);
        break;

      case STATUS_ALERT:
        g_running = 1;
        pthread_create(&g_anim_thread, NULL, breath_thread, NULL);
        break;

      case STATUS_SLEEP:
        anim_stop();
        g_visible = 0;
        draw_bar(COLOR_BLACK);
        break;
    }
}

void status_bar_acknowledge(void)
{
  if (g_status == STATUS_ALERT)
    {
      anim_stop();
      g_status = STATUS_NORMAL;
      draw_bar(COLOR_GREEN);
    }
}

void status_bar_hide(void)
{
  anim_stop();
  g_visible = 0;
  draw_bar(COLOR_BLACK);
}

void status_bar_show(void)
{
  g_visible = 1;
  draw_bar(COLOR_GREEN);
  g_status = STATUS_NORMAL;
}

enum device_status status_bar_get(void)
{
  return g_status;
}

/****************************************************************************
 * motor.c — 马达震动模式封装（无 LVGL 依赖版）
 *
 * 驱动接口：/dev/pwm0 (GPTIM1_CH3)
 * 非阻塞：pthread 驱动震动序列
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <nuttx/timers/pwm.h>
#include <fixedmath.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#include "motor.h"

#define MOTOR_PWM_DEV   "/dev/pwm0"
#define MOTOR_PWM_FREQ  200
#define PCT_TO_UB16(p)  ((p) >= 100 ? ub16MAX : b16divi(uitoub16(p) - 1, 100))

static int       g_pwm_fd   = -1;
static pthread_t g_seq_thread;
static volatile int g_running = 0;

/* ── PWM 底层 ────────────────────────────────────────────────────── */

static void pwm_set(uint8_t pct)
{
  struct pwm_info_s info;
  if (g_pwm_fd < 0) return;
  memset(&info, 0, sizeof(info));
  info.frequency = MOTOR_PWM_FREQ;
  info.duty = PCT_TO_UB16(pct);
  ioctl(g_pwm_fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
}

static void pwm_on(void)  { if (g_pwm_fd >= 0) ioctl(g_pwm_fd, PWMIOC_START, 0); }
static void pwm_off(void) { if (g_pwm_fd >= 0) ioctl(g_pwm_fd, PWMIOC_STOP, 0); }

static void motor_vibrate(int ms)
{
  pwm_set(100); pwm_on();
  usleep(ms * 1000);
  pwm_off(); pwm_set(0);
}

static void seq_stop(void)
{
  if (g_running)
    {
      g_running = 0;
      pthread_join(g_seq_thread, NULL);
    }
  pwm_off(); pwm_set(0);
}

/* ── 震动序列线程 ────────────────────────────────────────────────── */

static void *notify_thread(void *arg)
{
  LV_UNUSED(arg);
  motor_vibrate(200);
  g_running = 0;
  return NULL;
}

static void *alert_thread(void *arg)
{
  LV_UNUSED(arg);
  for (int i = 0; i < 3 && g_running; i++)
    {
      motor_vibrate(200);
      if (i < 2 && g_running) usleep(150000);
    }
  g_running = 0;
  return NULL;
}

static void *wakeup_thread(void *arg)
{
  LV_UNUSED(arg);
  motor_vibrate(100);
  g_running = 0;
  return NULL;
}

static void seq_start(void *(*func)(void *))
{
  seq_stop();
  g_running = 1;
  pthread_create(&g_seq_thread, NULL, func, NULL);
}

/* ── 公开接口 ────────────────────────────────────────────────────── */

void motor_init(void)
{
  if (g_pwm_fd >= 0) return;
  g_pwm_fd = open(MOTOR_PWM_DEV, O_RDONLY);
  if (g_pwm_fd < 0)
    printf("[motor] open %s failed: %d\n", MOTOR_PWM_DEV, errno);
  else
    { pwm_set(0); printf("[motor] OK on %s\n", MOTOR_PWM_DEV); }
}

void motor_on(void)     { seq_stop(); pwm_set(100); pwm_on(); }
void motor_off(void)    { seq_stop(); }
void motor_notify(void) { seq_start(notify_thread); }
void motor_alert(void)  { seq_start(alert_thread); }
void motor_wakeup(void) { seq_start(wakeup_thread); }

void motor_deinit(void)
{
  seq_stop();
  if (g_pwm_fd >= 0) { close(g_pwm_fd); g_pwm_fd = -1; }
}

