/****************************************************************************
 * clock_widget.c — 时钟组件（RTC 实时更新）
 *
 * 功能：
 *   - 读取 /dev/rtc0 获取当前时间
 *   - 大字显示时间 HH:MM:SS
 *   - 显示日期 YYYY-MM-DD
 *   - 显示星期
 *   - 每秒自动刷新
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <nuttx/timers/rtc.h>

#include "ui_common.h"
#include "clock_widget.h"

/****************************************************************************
 * 私有数据
 ****************************************************************************/

static lv_obj_t *g_time_label  = NULL;
static lv_obj_t *g_date_label  = NULL;
static lv_obj_t *g_week_label  = NULL;
static lv_timer_t *g_timer     = NULL;

static const char *g_weekdays[] =
{
  "周日", "周一", "周二", "周三", "周四", "周五", "周六"
};

/****************************************************************************
 * 读取 RTC 时间
 ****************************************************************************/

static int rtc_read(struct rtc_time *rt)
{
  int fd = open("/dev/rtc0", O_RDONLY);
  if (fd < 0) return -1;

  int ret = ioctl(fd, RTC_RD_TIME, (unsigned long)rt);
  close(fd);
  return ret;
}

/****************************************************************************
 * 更新显示
 ****************************************************************************/

static void clock_update_cb(lv_timer_t *timer)
{
  struct rtc_time rt;
  char buf[32];

  if (rtc_read(&rt) < 0)
    return;

  /* 时间 HH:MM:SS */

  snprintf(buf, sizeof(buf), "%02d:%02d:%02d",
           rt.tm_hour, rt.tm_min, rt.tm_sec);
  lv_label_set_text(g_time_label, buf);

  /* 日期 YYYY-MM-DD */

  snprintf(buf, sizeof(buf), "%04d-%02d-%02d",
           rt.tm_year + 1900, rt.tm_mon + 1, rt.tm_mday);
  lv_label_set_text(g_date_label, buf);

  /* 星期 */

  if (rt.tm_wday >= 0 && rt.tm_wday <= 6)
    lv_label_set_text(g_week_label, g_weekdays[rt.tm_wday]);
}

/****************************************************************************
 * 公开接口
 ****************************************************************************/

lv_obj_t *clock_widget_create(lv_obj_t *parent)
{
  /* 容器 */

  lv_obj_t *cont = lv_obj_create(parent);
  lv_obj_set_size(cont, 350, 160);
  lv_obj_set_style_bg_color(cont, COLOR_BG_CARD, 0);
  lv_obj_set_style_bg_opa(cont, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(cont, 16, 0);
  lv_obj_set_style_border_width(cont, 0, 0);
  lv_obj_set_style_pad_all(cont, 20, 0);
  lv_obj_remove_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_align(cont, LV_ALIGN_TOP_MID, 0, 30);

  /* Flex 布局：垂直居中 */

  lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(cont, 8, 0);

  /* 时间（大字） */

  g_time_label = ui_create_label(cont, "00:00:00",
                                 FONT_LARGE, COLOR_TEXT_WHITE);
  lv_obj_set_style_text_letter_space(g_time_label, 4, 0);

  /* 日期 */

  g_date_label = ui_create_label(cont, "2026-01-01",
                                 FONT_MEDIUM, COLOR_TEXT_GRAY);

  /* 星期 */

  g_week_label = ui_create_label(cont, "周一",
                                 FONT_SMALL, COLOR_TEXT_GREEN);

  /* 启动定时器：每秒刷新 */

  g_timer = lv_timer_create(clock_update_cb, 1000, NULL);
  lv_timer_ready(g_timer);  /* 立即触发首次更新 */

  return cont;
}

/****************************************************************************
 * popup.h — 弹窗组件
 * Contest 2026 Team 307
 ****************************************************************************/

#ifndef __POPUP_H
#define __POPUP_H

#include <lvgl.h>

/**
 * 弹窗确认回调
 */

typedef void (*popup_cb_t)(void *user_data);

/**
 * 创建弹窗
 * @param parent    父对象（通常是屏幕）
 * @param title     标题文字
 * @param content   内容文字
 * @param btn_text  按钮文字（NULL 则默认"确认"）
 * @param cb        确认回调（可为 NULL）
 * @param user_data 回调用户数据
 * @return 弹窗对象（可用 lv_obj_del 删除）
 */

lv_obj_t *popup_create(lv_obj_t *parent, const char *title,
                       const char *content, const char *btn_text,
                       popup_cb_t cb, void *user_data);

/**
 * 关闭弹窗（带动画）
 */

void popup_close(lv_obj_t *popup);

#endif

/****************************************************************************
 * popup.c — 弹窗组件
 *
 * 结构：半透明遮罩 + 白色卡片 + 标题 + 内容 + 确认按钮
 * 支持：点击按钮关闭，回调通知
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include "ui_common.h"
#include "popup.h"

/****************************************************************************
 * 弹窗上下文
 ****************************************************************************/

struct popup_ctx
{
  popup_cb_t  cb;
  void       *user_data;
  lv_obj_t   *popup;      /* 最外层遮罩 */
};

/****************************************************************************
 * 按钮回调
 ****************************************************************************/

static void btn_confirm_cb(lv_event_t *e)
{
  struct popup_ctx *ctx = (struct popup_ctx *)lv_event_get_user_data(e);
  if (ctx->cb)
    ctx->cb(ctx->user_data);
  popup_close(ctx->popup);
  lv_free(ctx);
}

static void overlay_click_cb(lv_event_t *e)
{
  /* 点击遮罩空白区域也关闭 */

  struct popup_ctx *ctx = (struct popup_ctx *)lv_event_get_user_data(e);
  popup_close(ctx->popup);
  lv_free(ctx);
}

/****************************************************************************
 * 公开接口
 ****************************************************************************/

lv_obj_t *popup_create(lv_obj_t *parent, const char *title,
                       const char *content, const char *btn_text,
                       popup_cb_t cb, void *user_data)
{
  struct popup_ctx *ctx = lv_malloc(sizeof(struct popup_ctx));
  ctx->cb       = cb;
  ctx->user_data = user_data;

  /* 半透明遮罩层 */

  lv_obj_t *overlay = lv_obj_create(parent);
  lv_obj_set_size(overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
  lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
  lv_obj_set_style_bg_opa(overlay, LV_OPA_60, 0);
  lv_obj_set_style_border_width(overlay, 0, 0);
  lv_obj_set_style_radius(overlay, 0, 0);
  lv_obj_remove_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_align(overlay, LV_ALIGN_TOP_LEFT, 0, 0);

  ctx->popup = overlay;

  /* 点击遮罩关闭 */

  lv_obj_add_event_cb(overlay, overlay_click_cb, LV_EVENT_CLICKED, ctx);

  /* 白色卡片 */

  lv_obj_t *card = lv_obj_create(overlay);
  lv_obj_set_size(card, 320, 220);
  lv_obj_set_style_bg_color(card, COLOR_BG_CARD, 0);
  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(card, 16, 0);
  lv_obj_set_style_border_width(card, 0, 0);
  lv_obj_set_style_pad_all(card, 20, 0);
  lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_center(card);

  /* Flex 布局 */

  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(card, 12, 0);

  /* 阻止卡片点击事件冒泡到遮罩 */

  lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_add_event_cb(card, NULL, LV_EVENT_CLICKED, NULL);

  /* 标题 */

  ui_create_label(card, title, FONT_LARGE, COLOR_TEXT_WHITE);

  /* 分隔线 */

  lv_obj_t *line = lv_obj_create(card);
  lv_obj_set_size(line, 260, 1);
  lv_obj_set_style_bg_color(line, COLOR_TEXT_GRAY, 0);
  lv_obj_set_style_bg_opa(line, LV_OPA_30, 0);
  lv_obj_set_style_border_width(line, 0, 0);

  /* 内容 */

  lv_obj_t *content_label = ui_create_label(card, content,
                                            FONT_MEDIUM, COLOR_TEXT_GRAY);
  lv_obj_set_width(content_label, 260);
  lv_label_set_long_mode(content_label, LV_LABEL_LONG_WRAP);
  lv_obj_set_style_text_align(content_label, LV_TEXT_ALIGN_CENTER, 0);

  /* 确认按钮 */

  const char *text = btn_text ? btn_text : "确认";
  lv_obj_t *btn = ui_create_button(card, 200, 44, text, btn_confirm_cb);
  lv_obj_add_event_cb(btn, btn_confirm_cb, LV_EVENT_CLICKED, ctx);

  return overlay;
}

void popup_close(lv_obj_t *popup)
{
  if (popup)
    lv_obj_del(popup);
}

/****************************************************************************
 * reminder_page.c — 全屏课程提醒页面
 *
 * 大字显示课程名 + 地点 + 时间，带确认按钮
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include "ui_common.h"
#include "reminder_page.h"
#include "popup.h"

/****************************************************************************
 * 按钮回调：关闭提醒页
 ****************************************************************************/

static void btn_ok_cb(lv_event_t *e)
{
  lv_obj_t *page = (lv_obj_t *)lv_event_get_user_data(e);
  if (page)
    lv_obj_del(page);
}

/****************************************************************************
 * 公开接口
 ****************************************************************************/

lv_obj_t *reminder_page_create(lv_obj_t *parent, const char *course,
                                const char *location, const char *time_str)
{
  /* 全屏半透明背景 */

  lv_obj_t *page = lv_obj_create(parent);
  lv_obj_set_size(page, SCREEN_WIDTH, SCREEN_HEIGHT);
  lv_obj_set_style_bg_color(page, lv_color_hex(0x0D1B2A), 0);
  lv_obj_set_style_bg_opa(page, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(page, 0, 0);
  lv_obj_set_style_radius(page, 0, 0);
  lv_obj_remove_flag(page, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_align(page, LV_ALIGN_TOP_LEFT, 0, 0);

  /* Flex 布局：垂直居中 */

  lv_obj_set_flex_flow(page, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(page, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(page, 16, 0);

  /* 顶部装饰条 */

  lv_obj_t *bar = lv_obj_create(page);
  lv_obj_set_size(bar, 60, 4);
  lv_obj_set_style_bg_color(bar, COLOR_TEXT_RED, 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(bar, 2, 0);
  lv_obj_set_style_border_width(bar, 0, 0);

  /* 提示文字 */

  ui_create_label(page, "📢 课程提醒", FONT_SMALL, COLOR_TEXT_RED);

  /* 课程名（大字） */

  lv_obj_t *course_label = ui_create_label(page, course,
                                           FONT_LARGE, COLOR_TEXT_WHITE);
  lv_obj_set_style_text_letter_space(course_label, 2, 0);

  /* 分隔线 */

  lv_obj_t *sep = lv_obj_create(page);
  lv_obj_set_size(sep, 200, 1);
  lv_obj_set_style_bg_color(sep, COLOR_TEXT_GRAY, 0);
  lv_obj_set_style_bg_opa(sep, LV_OPA_30, 0);
  lv_obj_set_style_border_width(sep, 0, 0);

  /* 地点 */

  char loc_buf[64];
  snprintf(loc_buf, sizeof(loc_buf), "📍 %s", location);
  ui_create_label(page, loc_buf, FONT_MEDIUM, COLOR_TEXT_GREEN);

  /* 时间 */

  char time_buf[64];
  snprintf(time_buf, sizeof(time_buf), "🕐 %s", time_str);
  ui_create_label(page, time_buf, FONT_MEDIUM, COLOR_TEXT_BLUE);

  /* 间距 */

  lv_obj_t *spacer = lv_obj_create(page);
  lv_obj_set_size(spacer, 1, 20);
  lv_obj_set_style_bg_opa(spacer, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(spacer, 0, 0);

  /* 确认按钮 */

  lv_obj_t *btn = ui_create_button(page, 240, 50, "知道了", btn_ok_cb);
  lv_obj_add_event_cb(btn, btn_ok_cb, LV_EVENT_CLICKED, page);

  return page;
}

/****************************************************************************
 * day2_ui_main.c — Day 2 UI 主入口
 *
 * 用法：nsh> day2_ui
 *
 * 功能：
 *   - 初始化 LVGL + 显示
 *   - 创建主界面（时钟 + 测试按钮）
 *   - 测试弹窗和提醒页面
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "ui_common.h"
#include "clock_widget.h"
#include "popup.h"
#include "reminder_page.h"

/****************************************************************************
 * 按钮回调
 ****************************************************************************/

static void btn_popup_cb(lv_event_t *e)
{
  lv_obj_t *scr = lv_screen_active();
  popup_create(scr, "提示", "这是一条测试弹窗消息",
               "我知道了", NULL, NULL);
}

static void btn_reminder_cb(lv_event_t *e)
{
  lv_obj_t *scr = lv_screen_active();
  reminder_page_create(scr, "高等数学", "教学楼 A302", "14:00 - 15:35");
}

static void btn_reminder2_cb(lv_event_t *e)
{
  lv_obj_t *scr = lv_screen_active();
  reminder_page_create(scr, "嵌入式系统", "实验楼 B201", "16:00 - 17:35");
}

/****************************************************************************
 * 创建主界面
 ****************************************************************************/

static void create_main_ui(void)
{
  lv_obj_t *scr = lv_screen_active();

  /* 深色背景 */

  lv_obj_set_style_bg_color(scr, COLOR_BG_DARK, 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

  /* 时钟组件 */

  clock_widget_create(scr);

  /* 测试按钮区域 */

  lv_obj_t *btn_cont = lv_obj_create(scr);
  lv_obj_set_size(btn_cont, 350, 240);
  lv_obj_align(btn_cont, LV_ALIGN_TOP_MID, 0, 210);
  lv_obj_set_style_bg_opa(btn_cont, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(btn_cont, 0, 0);
  lv_obj_set_style_pad_all(btn_cont, 0, 0);
  lv_obj_remove_flag(btn_cont, LV_OBJ_FLAG_SCROLLABLE);

  lv_obj_set_flex_flow(btn_cont, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(btn_cont, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_row(btn_cont, 12, 0);

  /* 测试按钮 */

  ui_create_button(btn_cont, 280, 46, "弹窗测试", btn_popup_cb);
  ui_create_button(btn_cont, 280, 46, "课程提醒：高数", btn_reminder_cb);
  ui_create_button(btn_cont, 280, 46, "课程提醒：嵌入式", btn_reminder2_cb);

  /* 底部版本信息 */

  lv_obj_t *ver = ui_create_label(scr, "Day 2 UI Demo — Team 307",
                                  FONT_TINY, COLOR_TEXT_GRAY);
  lv_obj_align(ver, LV_ALIGN_BOTTOM_MID, 0, -16);
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t    dsc;
  lv_nuttx_result_t result;
  uint32_t          idle;

  printf("=== Day 2 UI Demo (Team 307) ===\n");

  /* 检查 LVGL 是否已初始化 */

  if (lv_is_initialized())
    {
      printf("LVGL already initialized, deinit first...\n");
      lv_nuttx_deinit(&result);
      lv_deinit();
    }

  /* LVGL 初始化 */

  lv_init();
  lv_nuttx_dsc_init(&dsc);

  dsc.fb_path    = "/dev/lcd0";
  dsc.input_path = "/dev/input0";

  lv_nuttx_init(&dsc, &result);

  if (result.disp == NULL)
    {
      printf("ERROR: display init failed\n");
      return -1;
    }

  printf("Display: %dx%d\n", SCREEN_WIDTH, SCREEN_HEIGHT);

  /* 创建主界面 */

  create_main_ui();

  printf("UI ready. Main loop running.\n");

  /* 主循环 */

  while (1)
    {
      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  lv_nuttx_deinit(&result);
  lv_deinit();

  return 0;
}

